			, t.[IsPreferred]
			, t.[CreatedDate]
		FROM [dbo].[SupplierMaterial] AS t
		LEFT JOIN [dbo].[Supplier] AS j1 ON j1.[Id] = t.[SupplierId]
		LEFT JOIN [dbo].[Ingredient] AS j2 ON j2.[Id] = t.[IngredientId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[SupplierMaterialCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@SupplierId IS NULL OR t.[SupplierId] = @SupplierId)
			AND (@IngredientId IS NULL OR t.[IngredientId] = @IngredientId)
			AND (@PurchaseUomId IS NULL OR t.[PurchaseUomId] = @PurchaseUomId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@EffectiveOn IS NULL OR ((t.[EffectiveFrom] IS NULL OR t.[EffectiveFrom] <= @EffectiveOn) AND (t.[EffectiveTo] IS NULL OR t.[EffectiveTo] >= @EffectiveOn)))
			AND (ISNULL(@SupplierMaterialCode, '') = '' OR t.[SupplierMaterialCode] LIKE CONCAT('%', @SupplierMaterialCode, '%'))
			AND (@UnitPrice IS NULL OR t.[UnitPrice] = @UnitPrice)
			AND (@MinimumOrderQuantity IS NULL OR t.[MinimumOrderQuantity] = @MinimumOrderQuantity)
			AND (@LeadTimeDays IS NULL OR t.[LeadTimeDays] = @LeadTimeDays)
			AND (ISNULL(@QualityRequirement, '') = '' OR t.[QualityRequirement] LIKE CONCAT('%', @QualityRequirement, '%'))
			AND (@EffectiveFrom IS NULL OR t.[EffectiveFrom] = @EffectiveFrom)
			AND (@EffectiveTo IS NULL OR t.[EffectiveTo] = @EffectiveTo)
			AND (@IsPreferred IS NULL OR t.[IsPreferred] = @IsPreferred)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'supplierId' THEN r.[SupplierId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'supplierId' THEN r.[SupplierId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'supplierName' THEN r.[SupplierName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'supplierName' THEN r.[SupplierName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'ingredientName' THEN r.[IngredientName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'ingredientName' THEN r.[IngredientName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'supplierMaterialCode' THEN r.[SupplierMaterialCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'supplierMaterialCode' THEN r.[SupplierMaterialCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'purchaseUomId' THEN r.[PurchaseUomId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'purchaseUomId' THEN r.[PurchaseUomId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'unitPrice' THEN r.[UnitPrice] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'unitPrice' THEN r.[UnitPrice] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'leadTimeDays' THEN r.[LeadTimeDays] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'leadTimeDays' THEN r.[LeadTimeDays] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryFrequency' THEN r.[DeliveryFrequency] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryFrequency' THEN r.[DeliveryFrequency] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'qualityRequirement' THEN r.[QualityRequirement] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'qualityRequirement' THEN r.[QualityRequirement] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'minimumOrderQuantity' THEN r.[MinimumOrderQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'minimumOrderQuantity' THEN r.[MinimumOrderQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'isPreferred' THEN r.[IsPreferred] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'isPreferred' THEN r.[IsPreferred] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
